     raise AssertionError(label+"; last="+str(last))
    try:
     wait(lambda:request("/-/ready")[0]==200,"server not ready",8)
     if CASE["mode"]=="reload":
      wait(lambda:len(query('demo_requests_total{config_version="v1"}'))==2,"baseline not scraped")
      write(job);code,data=request("/-/reload",True);assert code==200,"candidate reload rejected: "+data.decode(errors="replace")
      since=time.time()
      wait(lambda:len(query('demo_requests_total{config_version="v2",service="shop"}'))==2 and all(float(x["value"][1])>=since for x in query('timestamp(demo_requests_total{config_version="v2",service="shop"})')),"v2 not effective")
