      code,_=request("/-/reload",True);assert code>=400,"invalid reload accepted"
      since=time.time()
      wait(lambda:len(query('timestamp(demo_requests_total{config_version="v2",service="shop"})'))==2 and all(float(x["value"][1])>=since for x in query('timestamp(demo_requests_total{config_version="v2",service="shop"})')),"invalid reload damaged live config")
