      since=time.time()
      wait(lambda:len(query('timestamp(demo_requests_total{config_version="v1",service="shop"})'))==2 and all(float(x["value"][1])>=since for x in query('timestamp(demo_requests_total{config_version="v1",service="shop"})')),"rollback not effective")
