      if CASE["mode"]=="discovery":assert len(targets["droppedTargets"])==1,"lab target must remain dropped"
      health=query("up");assert len(health)==expected and all(x["value"][1]=="1" for x in health),"native scrape failed"
      business=query("demo_requests_total")
      assert len(business)==2*expected,"lost or added business series"
      assert sum(float(x["value"][1]) for x in business)==18*expected,"business values differ"
      for item in business:
       labels=item["metric"];value=float(item["value"][1])
       assert labels.get("path") in ["/pay","/browse"] and value=={"/pay":7,"/browse":11}[labels["path"]]
       assert labels.get("env")=="prod" and labels.get("service")=="shop"
       assert not any(k.startswith("__meta_") for k in labels)
       if CASE["mode"]=="address":assert labels.get("instance")=="checkout-api" and "real_address" not in labels
      if CASE["mode"]=="meta":assert {x["metric"].get("zone") for x in business}=={"cn-east","cn-west"}
      if CASE["mode"]=="discovery":assert {x["metric"].get("region") for x in business}=={"cn-east","cn-west"}
      if CASE["mode"] in ["budget","stages"]:assert query("debug_session_bytes")==[],"debug family leaked"
      if CASE["mode"]=="budget":
       healthdata=query("app_health");assert len(healthdata)==1 and healthdata[0]["value"][1]=="1"
      print("native scrape and business contract passed")
    finally:
     stop.set()
     if proc.poll() is None:
      proc.terminate()
      try:proc.wait(timeout=4)
      except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=4)
     stats["terminated"]=proc.poll() is not None
     if guard:guard.join(timeout=2)
     assert not guard_fail,"resource guard fired: "+repr(guard_fail)
 finally:
  stop.set()
  if proc is not None and proc.poll() is None:proc.kill();proc.wait(timeout=4)
  if guard:guard.join(timeout=2)
  for server in servers:server.shutdown();server.server_close()
  for t in threads:t.join(timeout=2)
  print("native child lifecycle:",json.dumps(stats))

